function beta_cc_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'message' => $msg]); exit();
}
