    $bBool = function ($k) { if (!in_array((string) ($_POST[$k] ?? ''), ['0', '1'], true)) beta_cc_fail('Invalid on/off value.'); if ($_POST[$k] === '0') unset($_POST[$k]); };
    if ($bCcAction === 'save') {
        foreach (['enabled', 'profanity_filter', 'action_tags_enabled', 'show_confidence'] as $k) $bBool($k);
        $bIn('font_size', 12, 120, 'Font size'); $bIn('max_lines', 1, 5, 'Maximum lines'); $bIn('fade_seconds', 0, 60, 'Fade after');
        if (!preg_match('/^#[0-9A-Fa-f]{6}$/', (string) ($_POST['text_color'] ?? ''))) beta_cc_fail('Text colour must be a hex code like #FFFFFF.');
        $_POST['cc_save'] = '1';
    } elseif ($bCcAction === 'save_corrections') {
        $rows = json_decode((string) ($_POST['rows'] ?? ''), true);
        if (!is_array($rows) || !array_is_list($rows) || count($rows) > 300) beta_cc_fail('Up to 300 corrections.');
        foreach ($rows as $r) {
            if (!is_array($r)) beta_cc_fail('Invalid correction.');
            foreach (['match_text', 'replace_text'] as $k) { $v = trim((string) ($r[$k] ?? '')); if ($v === '' || mb_strlen($v) > 255) beta_cc_fail('Heard and Correct need 1 to 255 characters each.'); }
            if (!in_array($r['match_mode'] ?? '', ['word', 'substring'], true)) beta_cc_fail('Invalid match mode.');
        }
        $_POST['cc_corrections_save'] = '1';
    } else beta_cc_fail('Unknown action.');
}
