            'match_mode' => ($ccCorrRow['match_mode'] === 'substring') ? 'substring' : 'word',
            'case_sensitive' => (int)$ccCorrRow['case_sensitive'] ? 1 : 0,
            'enabled' => (int)$ccCorrRow['enabled'] ? 1 : 0,
        ];
